{
  "name": "离散PI控制器",
  "name_en": "Discrete PI Controller",
  "manufacturer": "",
  "description": "一种执行比例-积分反馈调节的数字控制单元，根据设定值与测量反馈之间的偏差计算控制输出，并带有积分防饱和处理。可用于实验室中的温度、位置、光功率或其他过程量的闭环稳定控制。",
  "description_en": "A digital control unit that performs proportional-integral feedback control. It computes a control output from the error between a setpoint and a measured feedback value, with anti-windup handling for the integral term. It is suitable for closed-loop stabilization of temperature, position, optical power, or other process variables in laboratory setups.",
  "tag_hints": [
    "PI control",
    "feedback loop",
    "digital controller",
    "closed-loop regulation",
    "anti-windup",
    "process control"
  ],
  "actions": [
    {
      "action_name": "auto-controler_output",
      "description": "根据当前测量值计算PI控制输出",
      "description_en": "Calculate the PI control output from the current measured value."
    },
    {
      "action_name": "auto-read_probes",
      "description": "读取控制器的监测值或探针读数",
      "description_en": "Read the controller's monitored values or probe readings."
    },
    {
      "action_name": "auto-reset",
      "description": "重置控制器状态",
      "description_en": "Reset the controller state."
    },
    {
      "action_name": "auto-update",
      "description": "更新控制器设置参数",
      "description_en": "Update the controller settings."
    },
    {
      "action_name": "auto-is_connected",
      "description": "检查控制器是否已连接",
      "description_en": "Check whether the controller is connected."
    },
    {
      "action_name": "auto-quit",
      "description": "停止并退出控制器",
      "description_en": "Stop and quit the controller."
    }
  ]
}

